// RM0008 bxCAN, F103 only. Internal loopback uses the actual mailboxes,
// acceptance filters and RX FIFOs. No fabricated external bus acknowledgement.
const BASE=0x40006400;
export class STMCAN {
 constructor(r){this.r=r;this.reset();}
 reset(){this.mcr=0x10002;this.msr=2;this.tsr=0x1c000000;this.ier=0;this.esr=0;this.btr=0x1230000;this.fmr=1;this.fm1r=0;this.fs1r=0;this.ffa1r=0;this.fa1r=0;this.filters=Array.from({length:14},()=>[0,0]);this.tx=Array.from({length:3},()=>[0,0,0,0]);this.fifo=[[],[]];this.flags=[0,0];this.pending=[];this.tec=0;this.frames=0;}
 supported(){return this.r.board.cpu!=='cortex-m4f';}
 clocked(){return this.supported()&&!!(this.r.regs.get(0x4002101c)&(1<<25));}
 running(){return this.clocked()&&!(this.mcr&3);}
 shared(){if(this.r.regs.get(0x4002101c)&(1<<23))throw Error('STM32F103 USB ve CAN aynı 512 bayt SRAM’i paylaşır; birlikte çalıştırılamaz.');}
 irqExtra(){if(!this.clocked())return 0;return ((this.tsr&0x10101)&&(this.ier&1)?4:0)|((this.fifo[0].length&&(this.ier&2))||((this.flags[0]&8)&&(this.ier&4))||((this.flags[0]&16)&&(this.ier&8))?8:0)|((this.fifo[1].length&&(this.ier&16))||((this.flags[1]&8)&&(this.ier&32))||((this.flags[1]&16)&&(this.ier&64))?16:0)|((this.msr&4)&&(this.ier&0x8000)?32:0);}
 match(tir){const key=(tir&0xfffffffe)>>>0;for(let i=0;i<14;i++){if(!(this.fa1r&(1<<i)))continue;const [a,b]=this.filters[i],list=!!(this.fm1r&(1<<i)),wide=!!(this.fs1r&(1<<i));if(wide){if(list?(key===(a>>>0)||key===(b>>>0)):((key&(b>>>0))>>>0)===((a&(b>>>0))>>>0))return [this.ffa1r>>i&1,i];}else{const k=((tir>>>21)<<5)|((tir&2)<<3)|((tir&4)<<1)|((tir>>>18)&7),v=[a&65535,a>>>16,b&65535,b>>>16];if(list?v.includes(k):((k&v[1])===(v[0]&v[1])||(k&v[3])===(v[2]&v[3])))return [this.ffa1r>>i&1,i];}}return null;}
 receive(frame){if(!this.running()||(this.fmr&1))return false;const match=this.match(frame[0]);if(!match)return false;const [q,index]=match,f=this.fifo[q],copy=[frame[0]&0xfffffffe,((frame[1]&15)|(index<<8))>>>0,frame[2]>>>0,frame[3]>>>0];if(f.length===3){this.flags[q]|=16;if(!(this.mcr&8))f[2]=copy;}else f.push(copy);if(f.length===3)this.flags[q]|=8;return true;}
 tick(){if(!this.running())return;for(const job of [...this.pending])if(this.r.count>=job.at){this.pending.splice(this.pending.indexOf(job),1);const i=job.i,shift=8*i,frame=this.tx[i];frame[0]&=~1;this.tsr|=(1<<(26+i))|(1<<shift);if(this.btr&0x40000000){this.tsr|=2<<shift;this.frames++;this.receive(frame);}else{this.tsr|=8<<shift;this.tec=Math.min(256,this.tec+8);this.esr=(3<<4)|((Math.min(255,this.tec))<<16)|(this.tec>=96?1:0)|(this.tec>=128?2:0)|(this.tec>=256?4:0);this.msr|=4;/* deterministic no-ACK completion; automatic retransmission is deliberately unsupported */}}}
 access(a,n){if(a<BASE||a>=BASE+0x400)return false;if(!this.supported())throw Error('Bu STM32F401/F411 kartında CAN denetleyicisi yok.');if(a%4||n!==4)throw Error('bxCAN register erişimi hizalı 32 bit olmalı.');return true;}
 read(a,n){if(!this.access(a,n))return undefined;this.tick();if(!this.clocked())return 0;const o=a-BASE;if(o===0)return this.mcr>>>0;if(o===4)return this.msr;if(o===8){let code=this.tx.findIndex((_,i)=>this.tsr&(1<<(26+i)));return (this.tsr|((Math.max(0,code)&3)<<24))>>>0;}if(o===12||o===16){const q=(o-12)/4;return this.fifo[q].length|this.flags[q];}if(o===20)return this.ier;if(o===24)return this.esr>>>0;if(o===28)return this.btr>>>0;if(o>=0x180&&o<0x1b0)return this.tx[Math.floor((o-0x180)/16)][(o%16)/4]>>>0;if(o>=0x1b0&&o<0x1d0)return (this.fifo[Math.floor((o-0x1b0)/16)][0]||[0,0,0,0])[(o%16)/4]>>>0;if(o===0x200)return this.fmr;if(o===0x204)return this.fm1r;if(o===0x20c)return this.fs1r;if(o===0x214)return this.ffa1r;if(o===0x21c)return this.fa1r;if(o>=0x240&&o<0x2b0)return this.filters[Math.floor((o-0x240)/8)][(o%8)/4]>>>0;throw Error('bxCAN register kapsam dışı: 0x'+a.toString(16));}
 write(a,v,n){if(!this.access(a,n))return false;if(!this.clocked())return true;this.shared();v>>>=0;this.tick();const o=a-BASE;if(o===0){if(v&0x8000){this.reset();return true;}this.mcr=v&0x100ff;this.msr=(this.msr&~3)|(v&3);return true;}if(o===4){this.msr&=~(v&0x1c);return true;}if(o===8){for(let i=0;i<3;i++){const s=i*8;if(v&(1<<s))this.tsr&=~(15<<s);if(v&(128<<s)){this.pending=this.pending.filter(j=>j.i!==i);this.tx[i][0]&=~1;this.tsr|=(1<<(26+i))|(1<<s);}}return true;}if(o===12||o===16){const q=(o-12)/4;if(v&32)this.fifo[q].shift();this.flags[q]&=~(v&24);return true;}if(o===20){this.ier=v&0x38f7f;return true;}if(o===24){this.esr=(this.esr&~0x70)|(v&0x70);return true;}if(o===28){if(this.mcr&1)this.btr=v&0xc37f03ff;return true;}if(o>=0x180&&o<0x1b0){const i=Math.floor((o-0x180)/16),word=(o%16)/4;if(!(this.tsr&(1<<(26+i))))return true;this.tx[i][word]=v;if(word===0&&(v&1)&&this.running()){if((this.tx[i][1]&15)>8)throw Error('CAN DLC en fazla 8 bayt olmalı.');if(!(this.btr&0x40000000)&&!(this.mcr&16))throw Error('Harici CAN bus modeli yok; normal mod için NART kullanın veya dahili loopback seçin.');this.tsr&=~(1<<(26+i));const tq=(this.btr&1023)+1,bits=1+((this.btr>>>16)&15)+1+((this.btr>>>20)&7)+1;this.pending.push({i,at:this.r.count+(50+8*(this.tx[i][1]&15))*tq*bits*2});}return true;}if(o>=0x1b0&&o<0x1d0)return true;if(o===0x200){this.fmr=v&1;return true;}if([0x204,0x20c,0x214,0x21c].includes(o)){if(this.fmr&1)this[{516:'fm1r',524:'fs1r',532:'ffa1r',540:'fa1r'}[o]]=v&0x3fff;return true;}if(o>=0x240&&o<0x2b0){if(this.fmr&1)this.filters[Math.floor((o-0x240)/8)][(o%8)/4]=v;return true;}throw Error('bxCAN register yazımı kapsam dışı: 0x'+a.toString(16));}
}
